#!/usr/bin/env bash
# ==============================================================================
# Itarang Phase 3 — poller hotfix v5
# Run as root on the Hostinger VPS.
#
# Cosmetic only:
#   - The offline alert message no longer hardcodes "30 min". It now derives
#     from OFFLINE_SEC (currently 60), so future threshold changes update the
#     message automatically.
#   - One-shot SQL UPDATE rewrites any currently-open alerts that still say
#     "No GPS for >30 min" so the dashboard renders consistent text immediately
#     instead of waiting for natural alert cycling.
#
# Steps:
#   1. Backup current poll.py
#   2. Write new poll.py via base64 (md5-verified, auto-rollback on mismatch)
#   3. Rebuild poller image and restart container
#   4. Run the SQL cleanup
#   5. Show 5 sample updated alerts to confirm
# ==============================================================================
set -euo pipefail

STORAGE_DIR=/opt/intellicar/storage
POLL_FILE="$STORAGE_DIR/poller/poll.py"
EXPECTED_MD5="17e67c946f1dc4eb35c1d77aa2add449"

cd "$STORAGE_DIR"

echo "==> [1/4] Backing up current poller/poll.py"
cp "$POLL_FILE" "$POLL_FILE.bak.v5.$(date +%s)"
ls -la "$STORAGE_DIR/poller/" | grep poll.py | tail -3

echo "==> [2/4] Writing new poller/poll.py (base64, md5-verified)"
base64 -d > "$POLL_FILE" <<'B64_EOF'

B64_EOF

ACTUAL_MD5=$(md5sum "$POLL_FILE" | awk '{print $1}')
if [ "$ACTUAL_MD5" != "$EXPECTED_MD5" ]; then
  echo "    ERROR: md5 mismatch. expected=$EXPECTED_MD5 actual=$ACTUAL_MD5"
  echo "    Restoring most recent backup..."
  cp "$(ls -t $POLL_FILE.bak.* | head -1)" "$POLL_FILE"
  exit 1
fi
echo "    md5 ok ($ACTUAL_MD5)"
echo "    new file: $(wc -l < $POLL_FILE) lines"

echo "==> [3/4] Rebuilding poller image and restarting container"
docker compose build poller
docker compose up -d poller
docker compose ps poller

echo "==> [4/4] Updating existing open offline alerts (message text only)"
docker compose exec -T postgres psql -U intellicar intellicar <<'SQL_EOF'
UPDATE alerts
SET message = 'No GPS for >60 min'
WHERE alert_type = 'offline'
  AND resolved_at IS NULL
  AND message = 'No GPS for >30 min';

-- Sanity: any alerts still on the old text? (should be 0 — only resolved ones if any)
SELECT
  COUNT(*) FILTER (WHERE message = 'No GPS for >30 min' AND resolved_at IS NULL) AS still_old_open,
  COUNT(*) FILTER (WHERE message = 'No GPS for >60 min' AND resolved_at IS NULL) AS new_open,
  COUNT(*) FILTER (WHERE alert_type = 'offline' AND resolved_at IS NULL) AS total_open_offline
FROM alerts;

-- Show 5 freshest open alerts to confirm rendered text
SELECT time, vehicleno, message
FROM alerts
WHERE alert_type = 'offline' AND resolved_at IS NULL
ORDER BY time DESC LIMIT 5;
SQL_EOF

echo ""
echo "================================================================="
echo " Hotfix v5 complete."
echo ""
echo " Refresh http://localhost:8090 — the alerts strip should now show"
echo " 'No GPS for >60 min' instead of the stale '>30 min' text."
echo "================================================================="
